-- Round 4: a messy set of accounts left behind by "the previous admin".
-- DO NOT EDIT THIS FILE. The grader always uses the instructor's copy.
-- bootstrap.sh runs it as root, after schema.sql and load.sql, and then runs your fixes.sql.
-- It starts by dropping these accounts, so it is safe to run again and again.

DROP USER IF EXISTS
  's6705142030_webapp'@'%', 's6705142030_webapp'@'localhost',
  's6705142030_kiosk'@'localhost', 's6705142030_kiosk'@'%',
  's6705142030_intern'@'%', 's6705142030_intern'@'localhost',
  's6705142030_etl'@'localhost', 's6705142030_etl'@'%',
  's6705142030_report'@'localhost', 's6705142030_report'@'%';

CREATE USER 's6705142030_webapp'@'%' IDENTIFIED BY 'Webapp#2026';
